// Shared generator helpers: naming, headers, and per-output callback props.
import type { ComponentIR, OutputIR } from '../ir.js';
import { toClassName } from '../manifest.js';

export const HEADER =
  '/// <reference lib="dom" />\n// Generated by gyral-cem. Do not edit.\n';

export const componentInterface = (component: ComponentIR): string =>
  `${component.exportName ?? toClassName(component.tag)}Element`;

/** `onAddedToCart` for `_tag: 'AddedToCart'`. */
export const callbackName = (output: OutputIR): string => `on${output.tag}`;

/** Attribute assignments for JSX/HTML attrs: `sku?: string`. */
export function attributeEntries(component: ComponentIR): string[] {
  return component.props
    .filter((prop) => prop.attribute !== undefined)
    .map((prop) => {
      const optional = prop.required ? '' : '?';
      return `      '${prop.attribute as string}'${optional}: ${prop.typeText};`;
    });
}

/** Property-only props stay settable as properties in framework bindings. */
export function propertyEntries(component: ComponentIR): string[] {
  return component.props
    .filter((prop) => prop.attribute === undefined)
    .map((prop) => {
      const optional = prop.required ? '' : '?';
      return `      ${prop.name}${optional}: ${prop.typeText};`;
    });
}

/** Per-output typed callbacks plus the raw `gyral-output` listener. */
export function eventEntries(component: ComponentIR, detailWrapper: (payload: string) => string): string[] {
  const entries = component.outputs.flatMap((output) => [
    `      /** Fires as \`gyral-output\` with \`detail._tag === '${output.tag}'\`. */`,
    `      ${callbackName(output)}?: (msg: ${output.payloadText}) => void;`,
  ]);
  if (component.outputs.length > 0) {
    entries.push(
      `      'on${'gyral-output'}'?: (event: ${detailWrapper(component.outputs.map((o) => o.payloadText).join(' | '))}) => void;`,
    );
  }
  return entries;
}

/** Union of known tags for generic tooling: `'a' | 'b'` (or `never`). */
export function tagsUnion(components: readonly ComponentIR[]): string {
  return components.length === 0 ? 'never' : components.map((c) => `'${c.tag}'`).join(' | ');
}
